Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Mass m₂ (kg), m₁ = 2 kg: <output id="m2MassVal">4</output>
<input id="m2MassInput" type="range" min="1" max="6" step="0.5" value="4" oninput="document.getElementById('m2MassVal').value=this.value;update_m2Mass(+this.value)"></label>
<button id="releaseBtn" onclick="trigger_releaseState()">Release the system</button>
<p id="demoNarration" style="margin:0;font-size:10px;max-width:180px;line-height:1.3">With the system held and m₂ heavier than m₁, both free-body diagrams show an identical upward tension T, but the downward weight w₂ is longer than w₁. The single cord transmits the same tension to both blocks.</p>
<div style="display:flex;align-items:center;gap:4px">
<button onclick="prevStep()">◀</button>
<span id="stepLabel" style="font-size:10px">Step 1/3</span>
<button onclick="nextStep()">▶</button>
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%','100%');
var W = 700, H = 480;
draw.viewbox(0, 0, W, H);

var m1 = 2, m2 = 4, g = 9.8;
var releaseState = 'held';
var releaseStates = ['held', 'released', 'later motion'];
var releaseIdx = 0;
var forceScale = 2.0, accelScale = 8.0;

var pulleyCx = 115, pulleyCy = 130, pulleyR = 40;
var cordLeftX = pulleyCx - pulleyR;
var cordRightX = pulleyCx + pulleyR;
var blockSize = 60;
var m1DefaultTop = 250, m2DefaultTop = 330;
var displacements = {'held':0,'released':20,'later motion':50};

var fbd1Cx = 380, fbd2Cx = 580, fbdCy = 240;
var fbdSize = 60;

var machineGroup = draw.group();
var fbdGroup = draw.group();

function getT(){ return 2*m1*m2*g/(m1+m2); }
function getA(){ return (m2-m1)*g/(m1+m2); }
function getW1(){ return m1*g; }
function getW2(){ return m2*g; }

function drawWoodBlock(grp, x, y, sz){
  grp.rect(sz,sz).move(x,y).fill('#f0d9a0').stroke('#c8a860').strokeWidth(1);
  for(var i=1;i<5;i++){
    var yy=y+i*sz/5;
    grp.path('M '+(x+3)+' '+yy+' Q '+(x+sz*0.25)+' '+(yy-3)+' '+(x+sz*0.5)+' '+yy+' Q '+(x+sz*0.75)+' '+(yy+3)+' '+(x+sz-3)+' '+yy)
      .fill('none').stroke('#d4b878').strokeWidth(1);
  }
}

function drawArrow(grp,x1,y1,x2,y2,color,w){
  grp.line(x1,y1,x2,y2).stroke({color:color,width:w});
  var ang=Math.atan2(y2-y1,x2-x1), hl=8, ha=Math.PI/6;
  var hx1=x2-hl*Math.cos(ang-ha), hy1=y2-hl*Math.sin(ang-ha);
  var hx2=x2-hl*Math.cos(ang+ha), hy2=y2-hl*Math.sin(ang+ha);
  grp.polygon([[x2,y2],[hx1,hy1],[hx2,hy2]]).fill(color);
}

function drawVectorLabel(grp, txt, sub, x, y){
  var t = grp.text(txt).font({family:'serif',style:'italic',size:13,weight:'bold'}).move(x,y).fill('#333');
  var bb = t.bbox();
  grp.line(bb.x, bb.y-2, bb.x+bb.width, bb.y-2).stroke({color:'#333',width:1});
  if(sub){
    grp.text(sub).font({family:'serif',size:9}).move(bb.x+bb.width+1, y+4).fill('#333');
  }
}

function update(){
  machineGroup.clear();
  fbdGroup.clear();
  var T=getT(), w1=getW1(), w2=getW2(), a=getA();
  var disp=displacements[releaseState]||0;
  var sign = m2>m1?1:(m2<m1?-1:0);
  var m1Top = m1DefaultTop - sign*disp;
  var m2Top = m2DefaultTop + sign*disp;

  // Ceiling
  machineGroup.rect(230,25).move(0,0).fill('#f5e6c8').stroke('#d4c4a0').strokeWidth(1);
  // Stem
  machineGroup.rect(8,45).move(pulleyCx-4,25).fill('#999').stroke('#777').strokeWidth(0.5);
  // Pulley
  machineGroup.circle(pulleyR*2).center(pulleyCx,pulleyCy).fill('#888').stroke('#666').strokeWidth(1.5);
  machineGroup.circle(pulleyR*1.5).center(pulleyCx,pulleyCy).fill('#aaa').stroke('#888').strokeWidth(1);
  machineGroup.circle(pulleyR*0.7).center(pulleyCx,pulleyCy).fill('#999').stroke('#777').strokeWidth(1);
  machineGroup.circle(6).center(pulleyCx,pulleyCy).fill('#666');

  // Cord
  machineGroup.line(cordLeftX,pulleyCy,cordLeftX,m1Top).stroke({color:'#d4a843',width:3});
  machineGroup.line(cordRightX,pulleyCy,cordRightX,m2Top).stroke({color:'#d4a843',width:3});
  machineGroup.path('M '+cordLeftX+' '+pulleyCy+' A '+pulleyR+' '+pulleyR+' 0 0 1 '+cordRightX+' '+pulleyCy)
    .fill('none').stroke({color:'#d4a843',width:3});

  // Block m1
  var m1L=cordLeftX-blockSize/2;
  drawWoodBlock(machineGroup,m1L,m1Top,blockSize);
  machineGroup.text('m').font({family:'serif',style:'italic',size:14}).move(m1L-28,m1Top+blockSize/2-8).fill('#333');
  machineGroup.text('1').font({family:'serif',size:10}).move(m1L-16,m1Top+blockSize/2-2).fill('#333');

  // Block m2
  var m2L=cordRightX-blockSize/2;
  drawWoodBlock(machineGroup,m2L,m2Top,blockSize);
  machineGroup.text('m').font({family:'serif',style:'italic',size:14}).move(m2L+blockSize+5,m2Top+blockSize/2-8).fill('#333');
  machineGroup.text('2').font({family:'serif',size:10}).move(m2L+blockSize+17,m2Top+blockSize/2-2).fill('#333');

  // === FBDs ===
  fbdGroup.text('Block 1').font({family:'sans-serif',size:14}).center(fbd1Cx,25).fill('#333');
  fbdGroup.text('Block 2').font({family:'sans-serif',size:14}).center(fbd2Cx,25).fill('#333');

  // Block 1
  var b1L=fbd1Cx-fbdSize/2, b1T=fbdCy-fbdSize/2;
  drawWoodBlock(fbdGroup,b1L,b1T,fbdSize);
  fbdGroup.text('m').font({family:'serif',style:'italic',size:13}).move(b1L-24,fbdCy-7).fill('#333');
  fbdGroup.text('1').font({family:'serif',size:9}).move(b1L-13,fbdCy-1).fill('#333');

  var tLen=T*forceScale;
  drawArrow(fbdGroup,fbd1Cx,b1T,fbd1Cx,b1T-tLen,'#cc2222',2.5);
  drawVectorLabel(fbdGroup,'T',null,fbd1Cx-20,b1T-tLen/2-7);

  var w1Len=w1*forceScale;
  drawArrow(fbdGroup,fbd1Cx,b1T+fbdSize,fbd1Cx,b1T+fbdSize+w1Len,'#cc2222',2.5);
  drawVectorLabel(fbdGroup,'w','1',fbd1Cx-20,b1T+fbdSize+w1Len/2-7);

  if(Math.abs(a)>0.05){
    var aLen=Math.abs(a)*accelScale;
    var aDir1=a>0?-1:1;
    var as1=b1T-5, ae1=as1+aDir1*aLen;
    drawArrow(fbdGroup,fbd1Cx+22,as1,fbd1Cx+22,ae1,'#2266cc',1.5);
    fbdGroup.text('a').font({family:'serif',style:'italic',size:11}).move(fbd1Cx+27,(as1+ae1)/2-5).fill('#2266cc');
    fbdGroup.text('1').font({family:'serif',size:8}).move(fbd1Cx+35,(as1+ae1)/2).fill('#2266cc');
  }

  // Block 2
  var b2L=fbd2Cx-fbdSize/2, b2T=fbdCy-fbdSize/2;
  drawWoodBlock(fbdGroup,b2L,b2T,fbdSize);
  fbdGroup.text('m').font({family:'serif',style:'italic',size:13}).move(b2L-24,fbdCy-7).fill('#333');
  fbdGroup.text('2').font({family:'serif',size:9}).move(b2L-13,fbdCy-1).fill('#333');

  drawArrow(fbdGroup,fbd2Cx,b2T,fbd2Cx,b2T-tLen,'#cc2222',2.5);
  drawVectorLabel(fbdGroup,'T',null,fbd2Cx-20,b2T-tLen/2-7);

  var w2Len=w2*forceScale;
  drawArrow(fbdGroup,fbd2Cx,b2T+fbdSize,fbd2Cx,b2T+fbdSize+w2Len,'#cc2222',2.5);
  drawVectorLabel(fbdGroup,'w','2',fbd2Cx-20,b2T+fbdSize+w2Len/2-7);

  if(Math.abs(a)>0.05){
    var aLen2=Math.abs(a)*accelScale;
    var aDir2=a>0?1:-1;
    var as2=b2T+fbdSize+5, ae2=as2+aDir2*aLen2;
    drawArrow(fbdGroup,fbd2Cx+22,as2,fbd2Cx+22,ae2,'#2266cc',1.5);
    fbdGroup.text('a').font({family:'serif',style:'italic',size:11}).move(fbd2Cx+27,(as2+ae2)/2-5).fill('#2266cc');
    fbdGroup.text('2').font({family:'serif',size:8}).move(fbd2Cx+35,(as2+ae2)/2).fill('#2266cc');
  }
}

function update_m2Mass(v){ m2=v; update(); }
function trigger_releaseState(){
  releaseIdx=(releaseIdx+1)%3;
  releaseState=releaseStates[releaseIdx];
  document.getElementById('releaseBtn').textContent =
    releaseState==='held'?'Release the system':
    releaseState==='released'?'Show later motion':'Reset (hold)';
  update();
}

var steps=[
  {title:'One cord, one tension',narration:'With the system held and m₂ heavier than m₁, both free-body diagrams show an identical upward tension T, but the downward weight w₂ is longer than w₁. The single cord transmits the same tension to both blocks.',state:{m2Mass:4,releaseState:'held'}},
  {title:'Sweep the mass difference',narration:'Drag the m₂ slider: the weight arrows and the small acceleration arrows grow or shrink, and at m₂ = m₁ the acceleration arrows vanish, yet the two T arrows remain equal at every setting — the tension is shared, the weight difference drives the motion.',state:{m2Mass:6,releaseState:'held'}},
  {title:'Release and watch equal opposite motion',narration:'Step through released to later motion: the heavier block moves down while the lighter block rises by the same distance, making visible that the two connected masses accelerate equally in opposite directions.',state:{m2Mass:4,releaseState:'later motion'}}
];
var curStep=0;

function applyStep(i){
  curStep=i;
  var s=steps[i].state;
  m2=s.m2Mass;
  document.getElementById('m2MassInput').value=m2;
  document.getElementById('m2MassVal').value=m2;
  releaseState=s.releaseState;
  releaseIdx=releaseStates.indexOf(releaseState);
  document.getElementById('releaseBtn').textContent=
    releaseState==='held'?'Release the system':
    releaseState==='released'?'Show later motion':'Reset (hold)';
  document.getElementById('demoNarration').textContent=steps[i].narration;
  document.getElementById('stepLabel').textContent='Step '+(i+1)+'/'+steps.length;
  update();
}
function nextStep(){ applyStep((curStep+1)%steps.length); }
function prevStep(){ applyStep((curStep-1+steps.length)%steps.length); }

update();
window.__markRendered();
// @FIGURE_CODE_END

