function drawWoodBlock(grp, x, y, sz){
  grp.rect(sz,sz).move(x,y).fill('#f0d9a0').stroke('#c8a860').strokeWidth(1);
  for(var i=1;i<5;i++){
    var yy=y+i*sz/5;
    grp.path('M '+(x+3)+' '+yy+' Q '+(x+sz*0.25)+' '+(yy-3)+' '+(x+sz*0.5)+' '+yy+' Q '+(x+sz*0.75)+' '+(yy+3)+' '+(x+sz-3)+' '+yy)
      .fill('none').stroke('#d4b878').strokeWidth(1);
  }
}

function drawArrow(grp,x1,y1,x2,y2,color,w){
  grp.line(x1,y1,x2,y2).stroke({color:color,width:w});
  var ang=Math.atan2(y2-y1,x2-x1), hl=8, ha=Math.PI/6;
  var hx1=x2-hl*Math.cos(ang-ha), hy1=y2-hl*Math.sin(ang-ha);
  var hx2=x2-hl*Math.cos(ang+ha), hy2=y2-hl*Math.sin(ang+ha);
  grp.polygon([[x2,y2],[hx1,hy1],[hx2,hy2]]).fill(color);
}

function drawVectorLabel(grp, txt, sub, x, y){
  var t = grp.text(txt).font({family:'serif',style:'italic',size:13,weight:'bold'}).move(x,y).fill('#333');
  var bb = t.bbox();
  grp.line(bb.x, bb.y-2, bb.x+bb.width, bb.y-2).stroke({color:'#333',width:1});
  if(sub){
    grp.text(sub).font({family:'serif',size:9}).move(bb.x+bb.width+1, y+4).fill('#333');
  }
}

